function nearestGrid(latlng){let best=-1,dist=Infinity;for(const i of analysis.publicLandGridIds){const dy=analysis.points[i*2]-latlng.lat,dx=(analysis.points[i*2+1]-latlng.lng)*Math.cos(latlng.lat*Math.PI/180),d=dx*dx+dy*dy;if(d<dist){dist=d;best=i}}return dist<=LAND_GRID_HIT_RADIUS2?best:-1}
