document.getElementById('openDetailModal').addEventListener('click',async()=>{useMapDetailContext();try{if(analysis.selectedGrid!==null)await selectGridSafely(analysis.selectedGrid,{showPanel:false})}catch(error){setDetailChartVisible(false);document.getElementById('detailGrid').textContent=`格子 ${analysis.selectedGrid??'未選択'}`;document.getElementById('detailMoisture').textContent='--';document.getElementById('detailLabel').textContent='読込失敗';document.getElementById('detailReason').textContent=`地点詳細を再読込できません: ${error.message}`}openDetailModal()});
