let legendDrag=null;document.getElementById('legendBox').addEventListener('pointerdown',event=>{const box=document.getElementById('legendBox'),rect=box.getBoundingClientRect(),host=document.querySelector('.map-stage').getBoundingClientRect();legendDrag={dx:event.clientX-rect.left,dy:event.clientY-rect.top};box.classList.add('dragging');box.style.left=`${rect.left-host.left}px`;box.style.top=`${rect.top-host.top}px`;box.style.right='auto';box.style.bottom='auto';box.setPointerCapture(event.pointerId)});document.getElementById('legendBox').addEventListener('pointermove',event=>{if(!legendDrag)return;const box=document.getElementById('legendBox'),host=document.querySelector('.map-stage').getBoundingClientRect(),rect=box.getBoundingClientRect(),maxLeft=Math.max(6,host.width-rect.width-6),maxTop=Math.max(6,host.height-rect.height-6);box.style.left=Math.max(6,Math.min(maxLeft,event.clientX-host.left-legendDrag.dx))+'px';box.style.top=Math.max(6,Math.min(maxTop,event.clientY-host.top-legendDrag.dy))+'px'});document.getElementById('legendBox').addEventListener('pointerup',event=>{legendDrag=null;event.currentTarget.classList.remove('dragging')});
map.on('click',async event=>{if(!analysis.values)return;const id=nearestGrid(event.latlng);if(id<0){setStatus('日本陸域の格子に近い場所を選んでください');return}try{useMapDetailContext();const expectedDetailSeq=analysis.detailSeq+1;await selectGridSafely(id,{showPanel:false});if(analysis.selectedGrid===id&&analysis.detailSeq===expectedDetailSeq)openDetailModal()}catch(error){setStatus(`地点詳細を開けません: ${error.message}`)}});
