function wateringLine(mode){const value=Number(analysis.presets?.operational_modes?.[mode]?.watering_line);if(!Number.isFinite(value))throw new Error(`presetsに${mode}の水やりラインがありません`);return value}
function itemDecision(value,mode){return value<=wateringLine(mode)?'水やり候補':'水やり不要'}
function reforecastContract(){const contract=analysis.manifest?.hourly?.reforecast,hours=analysis.manifest?.hourly?.times?.length,n=analysis.manifest?.grid_count;if(contract?.schema_version!==1||contract?.dtype!=='float32'||contract?.byte_order!=='little_endian'||contract?.layout!=='row_major_hours_grid'||contract?.bytes_per_value!==4||contract?.unit!=='percentage_points_per_hour'||JSON.stringify(contract?.shape)!==JSON.stringify([hours,n])||contract?.delta_index_semantics!=='delta_at_index_h_advances_state_from_h_minus_1_to_h'||contract?.event_application!=='after_transition_at_event_index'||contract?.water_full_target_pct!==95||contract?.water_light_increment_pct!==40)throw new Error('マイデータ再計算契約が不正です');return contract}
