function itemWaterEvents(item){if(!analysis.manifest)return[];const times=analysis.manifest.hourly.times.map(value=>new Date(value).getTime()),first=times[0],last=times.at(-1);return itemWaterLogRows(item).filter(row=>row.ts>=first&&row.ts<=last).map(row=>({...row,index:times.findIndex(value=>value>=row.ts)})).filter(row=>row.index>=0).sort((left,right)=>left.index-right.index||left.ts-right.ts||left.order-right.order)}
function itemDisplayIndex(forecast){return Math.max(analysis.manifest.current_index||0,forecast.events.at(-1)?.index??0)}
async function itemPlantForecast(item){if(!analysis.manifest||!MYDATA_PLANT_MODES.includes(item.mode))throw new Error('植物マイデータではありません');if(!Number.isInteger(item.grid_id)||!isPublicLandGrid(item.grid_id))throw new Error('陸域格子を再選択してください');const contract=reforecastContract(),refs=analysis.manifest.hourly.files[item.mode];if(!refs?.water_balance)throw new Error('マイデータ再計算用データがありません');const [moisture,balance,rain]=await Promise.all([buffer(refs.moisture,Uint8Array),buffer(refs.water_balance,Float32Array),buffer(analysis.manifest.hourly.rain,Float32Array)]),n=analysis.manifest.grid_count,count=analysis.manifest.hourly.times.length,expected=count*n;if(moisture.length!==expected||balance.length!==expected||rain.length!==expected)throw new Error('マイデータ再計算配列の長さが不正です');const values=new Float32Array(count),rainValues=new Float32Array(count);for(let h=0;h<count;h++){values[h]=moisture[h*n+item.grid_id];rainValues[h]=rain[h*n+item.grid_id]}const events=itemWaterEvents(item),byIndex=new Map(),firstTime=new Date(analysis.manifest.hourly.times[0]).getTime(),lastTime=new Date(analysis.manifest.hourly.times.at(-1)).getTime(),ignoredEvents=itemWaterLogRows(item).filter(row=>row.ts<firstTime||row.ts>lastTime);for(const event of events){if(!byIndex.has(event.index))byIndex.set(event.index,[]);byIndex.get(event.index).push(event)}if(events.length){const first=events[0].index;let state=values[first];for(let h=first;h<count;h++){if(h>first)state=Math.max(0,Math.min(100,state+balance[h*n+item.grid_id]));for(const event of byIndex.get(h)||[])state=event.log.type==='water_full'?contract.water_full_target_pct:Math.min(100,state+contract.water_light_increment_pct);values[h]=state}}return{values,rain:rainValues,events,ignoredEvents,contract}}
async function wateringTime(item,forecast=null){if(!analysis.manifest||item.mode==='medaka')return'--';if(analysis.landClasses&&!isPublicLandGrid(item.grid_id))return'再選択してください';const result=forecast||await itemPlantForecast(item),start=itemDisplayIndex(result),line=wateringLine(item.mode);for(let h=start;h<result.values.length;h++){if(result.values[h]<=line)return new Date(analysis.manifest.hourly.times[h]).toLocaleString('ja-JP',{timeZone:JST_TIME_ZONE,month:'numeric',day:'numeric',hour:'numeric'})}return'提供期間内は未到達'}
async function itemSummary(item){if(!analysis.manifest)return{status:'読込中',next:'--'};if(analysis.landClasses&&!isPublicLandGrid(item.grid_id))return{status:'陸域マスク外（旧登録）',next:'再選択してください'};if(item.mode==='medaka')return{status:'メダカ容器',next:'記録再計算は今後対応'};try{const forecast=await itemPlantForecast(item),index=itemDisplayIndex(forecast),value=Math.round(forecast.values[index]),time=shortJst(analysis.manifest.hourly.times[index]);return{status:`${value}%・${itemDecision(value,item.mode)}（${time}）`,next:await wateringTime(item,forecast)}}catch(error){return{status:'再計算データ待ち',next:error.message}}}
async function itemStatus(item){return(await itemSummary(item)).status}
async function renderItemCalendar(item,forecast,detailSeq=null){if(!analysis.daily){const response=await fetch(dataUrl(analysis.manifest.daily));if(!response.ok)throw new Error(`${analysis.manifest.daily} ${response.status}`);analysis.daily=await response.json()}if(detailSeq!==null&&detailSeq!==analysis.detailSeq)return false;const start=itemDisplayIndex(forecast),byDate=new Map();for(let h=start;h<analysis.manifest.hourly.times.length;h++){const date=new Date(analysis.manifest.hourly.times[h]).toLocaleDateString('sv-SE',{timeZone:JST_TIME_ZONE});if(!byDate.has(date))byDate.set(date,[]);byDate.get(date).push(forecast.values[h])}if(detailSeq!==null&&detailSeq!==analysis.detailSeq)return false;document.getElementById('calendarTitle').textContent=`管理カレンダー｜${item.name}`;document.getElementById('calendarDays').innerHTML=analysis.daily.days.map(day=>{const values=byDate.get(day.date);if(values?.length){const min=Math.round(Math.min(...values)),max=Math.round(Math.max(...values)),label=itemDecision(min,item.mode),klass=label==='水やり候補'?'caution':'';return`<article class="calendar-card ${klass}"><b>${escapeText(day.date)}</b><strong>${label}</strong><span>${min}〜${max}%</span><small>水やり記録を反映</small></article>`}const base=day.modes?.[item.mode],min=base?.min?.[item.grid_id],max=base?.max?.[item.grid_id],label=base?labelText(base.label[item.grid_id]):'週間傾向';return`<article class="calendar-card"><b>${escapeText(day.date)}</b><strong>${escapeText(label)}</strong><span>${Number.isFinite(min)?`${min}〜${max}%`:'--'}</span><small>週間傾向・個別記録未反映</small>${day.trend?'<span class="trend">傾向</span>':''}</article>`}).join('');return true}
function itemConditionText(item){const adjust=item.simple_adjust||{},mode=MYDATA_MODE_LABELS[item.mode]||String(item.mode||'未設定'),preset=MYDATA_PRESET_LABELS[item.preset_id]||String(item.preset_id||'未設定'),dryness=MYDATA_DRYNESS_LABELS[adjust.dryness]||String(adjust.dryness||'未設定'),rain=MYDATA_RAIN_LABELS[adjust.rain_exposure]||String(adjust.rain_exposure||'未設定'),note=item.mode==='medaka'?'メダカ記録の物理再計算は未対応です。':'かんたん補正は保存されていますが、水やり再計算は標準モードの水収支を使い、補正値はまだ物理再計算へ反映しません。';return`登録条件: ${mode}／プリセット ${preset}／乾きやすさ ${dryness}／雨の効きやすさ ${rain}。${note}`}
