setLegend=function(){setLegendWithInlineEndpoints();if(analysis.kind==='moisture'){document.getElementById('legendHigh').textContent='100 湿潤';document.getElementById('legendLow').textContent='0 乾燥'}};
const selectGridWithGridHeading=selectGrid;
selectGrid=async function(gridId,options={}){const locationPromise=resolveGridLocationLabel(gridId),result=await selectGridWithGridHeading(gridId,options),location=await locationPromise;if(analysis.selectedGrid!==gridId)return result;const detail=document.getElementById('detailGrid'),locationText=String(location||gridLocationLabel(gridId));detail.textContent=detail.textContent.replace(new RegExp(`^格子 ${gridId}`),locationText);detail.dataset.gridId=String(gridId);document.getElementById('itemGrid').value=locationText;const calendar=document.getElementById('calendarTitle');if(calendar.textContent.startsWith('管理カレンダー｜格子 '))calendar.textContent=`管理カレンダー｜${locationText}`;document.getElementById('floatingGrid').textContent=detail.textContent;return result};
const selectGridSafelyWithGridStatus=selectGridSafely;
selectGridSafely=async function(gridId,options={}){const result=await selectGridSafelyWithGridStatus(gridId,options);if(isPublicLandGrid(gridId)&&analysis.selectedGrid===gridId)setStatus(`${gridLocationLabel(gridId)}を選択`);return result};
const openItemDetailWithGridHeading=openItemDetail;
openItemDetail=async function(item){const locationPromise=resolveGridLocationLabel(item.grid_id),result=await openItemDetailWithGridHeading(item),location=await locationPromise;if(document.getElementById('detailModal').dataset.itemId!==item.id)return result;const detail=document.getElementById('detailGrid'),gridText=`｜格子 ${item.grid_id}｜${landGridLabel(item.grid_id)}`;detail.textContent=detail.textContent.replace(gridText,`｜${location}`);detail.dataset.gridId=String(item.grid_id);return result};
const drawExportLegendWithInlineEndpoints=drawExportLegend;
drawExportLegend=function(ctx,width){if(analysis.kind!=='moisture')return drawExportLegendWithInlineEndpoints(ctx,width);const title=document.getElementById('legendTitle').textContent,boxX=width-104,boxY=58,boxWidth=92,boxHeight=282,barX=boxX+10,barY=boxY+45,barWidth=24,barHeight=204,gradient=ctx.createLinearGradient(0,barY,0,barY+barHeight);ctx.save();['#1f5fa8','#4a90d9','#a8d08d','#e8c547','#b5651d'].forEach((color,index)=>gradient.addColorStop(index/4,color));ctx.fillStyle='#fffffff2';ctx.fillRect(boxX,boxY,boxWidth,boxHeight);ctx.strokeStyle='#9eb3ad';ctx.strokeRect(boxX+.5,boxY+.5,boxWidth-1,boxHeight-1);ctx.fillStyle='#17352f';ctx.font='bold 11px sans-serif';ctx.fillText(title,boxX+9,boxY+18);ctx.fillStyle='#49615b';ctx.font='bold 8px sans-serif';ctx.textAlign='center';ctx.fillText('湿潤',barX+barWidth/2,barY-10);ctx.fillText('乾燥',barX+barWidth/2,barY+barHeight+16);ctx.textAlign='left';ctx.fillStyle=gradient;ctx.fillRect(barX,barY,barWidth,barHeight);ctx.strokeStyle='#667b75';ctx.strokeRect(barX+.5,barY+.5,barWidth-1,barHeight-1);for(let i=0;i<=10;i++){const value=100-i*10,y=barY+barHeight*i/10;ctx.strokeStyle='#52645f';ctx.beginPath();ctx.moveTo(barX,y+.5);ctx.lineTo(barX+31,y+.5);ctx.stroke();ctx.fillStyle='#17352f';ctx.font='bold 9px sans-serif';ctx.fillText(`${value}%`,barX+36,y+3)}ctx.restore()};
map.on('mousemove',()=>{const tooltip=document.getElementById('tooltip');if(tooltip.hidden)return;const match=tooltip.textContent.match(/^格子 (\d+)｜[^｜]+/);if(match)tooltip.textContent=tooltip.textContent.replace(match[0],gridLocationLabel(Number(match[1])))});
renderItems().catch(error=>console.error(error));

function sharedTimeIndex(value){const raw=String(value||''),date=/^\d{10,13}$/.test(raw)?new Date(Number(raw)*(raw.length===10?1000:1)):new Date(raw),times=analysis.manifest.hourly.times,first=new Date(times[0]),last=new Date(times.at(-1));if(!Number.isFinite(date.getTime())||date<first||date>last)return analysis.manifest.current_index;return clampTimeIndex(timeIndexForValidtime(date.toISOString()))}
const SHARED_CONDITION_IDS=['mapPlant','mapSize','mapDrying','mapRain','mapSun','mapSpeed'];
function legacyWateringPolicy(drying,wet){const dryingScore={moist:-1,standard:0,dry:1,very_dry:2}[drying]??0,wetScore={weak:-1,normal:0,strong:1,very_strong:2}[wet]??0,total=dryingScore+wetScore;return total<0?'moist':total>0?'dry':'standard'}
function applySharedConditions(conditions){const values=conditions.slice(0,6),compat={mapPlant:{flower:'foliage'},mapDrying:{very_dry:'dry'},mapRain:{cover:'inside'},mapSun:{west:'sun'},mapSpeed:{very_fast:'fast'}};if(conditions.length>=7)values[2]=legacyWateringPolicy(conditions[2],conditions[6]);SHARED_CONDITION_IDS.forEach((id,index)=>{const raw=values[index],value=compat[id]?.[raw]||raw,element=document.getElementById(id);if(value&&[...element.options].some(option=>option.value===value))element.value=value})}
function applySharedState(){const params=new URLSearchParams(location.search),mode=params.get('mode'),kind=params.get('layer'),legacySlot=params.has('slot')?Number(params.get('slot')):null,sharedTime=params.get('time')||params.get('valid')||params.get('t'),aggregate=params.get('aggregate')||params.get('agg'),grid=params.has('grid')?Number(params.get('grid')):null,opacity=params.has('op')?Number(params.get('op')):null,base=params.get('base'),conditions=(params.get('c')||'').split(',');applySharedConditions(conditions);if(['pot_outdoor','ground','farm'].includes(mode)){analysis.mode=mode;document.getElementById('modeSelect').value=mode}if(['moisture','watering','rootrot','medaka'].includes(kind)){analysis.kind=kind;document.getElementById('analysisLayer').value=kind;document.getElementById('plantModeLabel').hidden=kind==='medaka';document.getElementById('medakaConditions').hidden=kind!=='medaka';document.getElementById('conditionNote').hidden=kind==='medaka'}analysis.pendingShortcut=null;analysis.viewKind='hourly';analysis.shortcutIndex=null;if(aggregate){const aggregateIndex=activeSlots().findIndex(slot=>slot.id===aggregate&&isAggregateSlot(slot));if(aggregateIndex>=0)analysis.pendingShortcut=aggregateIndex}else if(sharedTime){analysis.timeIndex=sharedTimeIndex(sharedTime)}else if(Number.isInteger(legacySlot)&&legacySlot>=0&&legacySlot<activeSlots().length){analysis.pendingShortcut=legacySlot}if(Number.isInteger(grid)&&grid>=0&&grid<analysis.manifest.grid_count){analysis.selectedGrid=grid;const lat=analysis.points?.[grid*2],lon=analysis.points?.[grid*2+1];if(Number.isFinite(lat)&&Number.isFinite(lon))map.setView([lat,lon],Math.max(6,Number(params.get('z'))||6))}if(opacity!==null&&Number.isFinite(opacity)&&opacity>=0&&opacity<=100){setAnalysisOpacity(opacity/100);document.getElementById('opacityRange').value=opacity}if(TILE[base])setBase(base);setTab('map')}
async function copyText(text){try{await navigator.clipboard.writeText(text);return true}catch{const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();const ok=document.execCommand('copy');area.remove();return ok}}
document.getElementById('copyLink').addEventListener('click',async()=>{const url=new URL("https://nature-wx-lab.github.io/water_care/"),target=selectedTarget();url.search='';url.searchParams.set('layer',analysis.kind);url.searchParams.set('mode',analysis.mode);if(target.timeSemantics==='window')url.searchParams.set('aggregate',target.id);else url.searchParams.set('time',target.validtime_jst);url.searchParams.set('base',activeBase);url.searchParams.set('op',Math.round(analysis.opacity*100));url.searchParams.set('z',map.getZoom());url.searchParams.set('c',SHARED_CONDITION_IDS.map(id=>document.getElementById(id).value).join(','));if(analysis.selectedGrid!==null)url.searchParams.set('grid',analysis.selectedGrid);const button=document.getElementById('copyLink');button.dataset.lastUrl=url.toString();button.dataset.viewKind=analysis.viewKind;button.dataset.validtime=target.validtime_jst;const ok=await copyText(url.toString());button.textContent=ok?'コピー済み':'コピー失敗';setTimeout(()=>button.textContent='リンクコピー',1200)});
function drawExportLegend(ctx,width){const title=document.getElementById('legendTitle').textContent;ctx.save();if(analysis.kind==='moisture'){const boxX=width-118,boxY=58,boxWidth=106,boxHeight=252,barX=boxX+10,barY=boxY+31,barWidth=24,barHeight=204,gradient=ctx.createLinearGradient(0,barY,0,barY+barHeight);['#1f5fa8','#4a90d9','#a8d08d','#e8c547','#b5651d'].forEach((color,index)=>gradient.addColorStop(index/4,color));ctx.fillStyle='#fffffff2';ctx.fillRect(boxX,boxY,boxWidth,boxHeight);ctx.strokeStyle='#9eb3ad';ctx.strokeRect(boxX+.5,boxY+.5,boxWidth-1,boxHeight-1);ctx.fillStyle='#17352f';ctx.font='bold 11px sans-serif';ctx.fillText(title,boxX+9,boxY+18);ctx.fillStyle=gradient;ctx.fillRect(barX,barY,barWidth,barHeight);ctx.strokeStyle='#667b75';ctx.strokeRect(barX+.5,barY+.5,barWidth-1,barHeight-1);for(let i=0;i<=10;i++){const value=100-i*10,y=barY+barHeight*i/10;ctx.strokeStyle='#52645f';ctx.beginPath();ctx.moveTo(barX,y+.5);ctx.lineTo(barX+31,y+.5);ctx.stroke();ctx.fillStyle='#17352f';ctx.font='bold 9px sans-serif';ctx.fillText(`${value}%`,barX+36,y+3);if(i===0||i===10){ctx.fillStyle='#5c6f69';ctx.font='bold 8px sans-serif';ctx.fillText(i===0?'十分':'乾燥',barX+(i===0?66:54),y+3)}}ctx.restore();return}const labels=[document.getElementById('legendHigh').textContent,document.getElementById('legendMid').textContent,document.getElementById('legendLow').textContent],colors=analysis.kind==='watering'?['#a23b3b','#2d87c8','#d95f02']:['#c62828','#f2c84b','#74add1'];ctx.fillStyle='#fffffff0';ctx.fillRect(width-155,58,143,112);ctx.fillStyle='#17352f';ctx.font='bold 12px sans-serif';ctx.fillText(title,width-145,76);ctx.font='10px sans-serif';labels.forEach((label,i)=>{ctx.fillStyle=colors[i];ctx.fillRect(width-145,87+i*24,18,14);ctx.fillStyle='#17352f';ctx.fillText(label,width-120,98+i*24)});ctx.restore()}
document.getElementById('saveImage').addEventListener('click',async()=>{const button=document.getElementById('saveImage');try{const mapElement=document.getElementById('map'),rect=mapElement.getBoundingClientRect(),scale=2,out=document.createElement('canvas'),target=selectedTarget();out.width=Math.round(rect.width*scale);out.height=Math.round(rect.height*scale);const ctx=out.getContext('2d');ctx.scale(scale,scale);ctx.fillStyle=activeBase==='pale'?'#e4eef5':'#fff';ctx.fillRect(0,0,rect.width,rect.height);const images=[...mapElement.querySelectorAll('.leaflet-tile-loaded')];await Promise.all(images.map(image=>image.decode?.().catch(()=>{})));let skippedExternal=0;for(const image of images){const r=image.getBoundingClientRect();try{ctx.drawImage(image,r.left-rect.left,r.top-rect.top,r.width,r.height)}catch{skippedExternal++}}if(analysis.canvas)ctx.drawImage(analysis.canvas,0,0,rect.width,rect.height);if(amedasRain.canvas&&!amedasRain.canvas.hidden)ctx.drawImage(amedasRain.canvas,0,0,rect.width,rect.height);drawExportLegend(ctx,rect.width);const notes=[];if(suikeiWeatherLayer||rainMotionLabel)notes.push('気象庁外部タイルはブラウザ制約により保存画像で一部省略される場合があります');if(skippedExternal)notes.push(`外部タイル ${skippedExternal}枚を保存画像から省略`);if(notes.length){ctx.fillStyle='#fff7e8f5';ctx.fillRect(10,12,Math.min(rect.width-20,560),20+notes.length*16);ctx.fillStyle='#6a3b00';ctx.font='11px sans-serif';notes.forEach((note,index)=>ctx.fillText(note,18,32+index*16))}ctx.fillStyle='#fffffff0';ctx.fillRect(10,rect.height-58,Math.min(rect.width-20,520),48);ctx.fillStyle='#17352f';ctx.font='bold 14px sans-serif';ctx.fillText('Nature Wx Lab｜うるおい管理ナビ',18,rect.height-38);ctx.font='11px sans-serif';const observed=amedasRain.enabled?`｜${amedasRain.label}`:suikeiWeatherLayer?'｜推計気象分布（最新）':'';ctx.fillText(`${target.label} ${shortJst(target.validtime_jst)}｜${target.source}｜格子 ${analysis.selectedGrid??'未選択'}${observed}｜出典: 気象庁データを加工`,18,rect.height-20);const link=document.createElement('a'),fileId=target.timeSemantics==='window'?target.id:new Date(target.validtime_jst).toISOString().replace(/[-:]/g,'').slice(0,13);link.href=out.toDataURL('image/png');link.download=`water_care-map-${fileId}.png`;button.dataset.imageReady=`${out.width}x${out.height}`;button.dataset.imageLegend=document.getElementById('legendTitle').textContent;button.dataset.imageViewKind=analysis.viewKind;button.dataset.imageValidtime=target.validtime_jst;button.dataset.imageSlotLabel=target.label;button.dataset.skippedExternal=String(skippedExternal);button.dataset.imageNotes=notes.join(' / ');delete button.dataset.imageError;link.click();button.textContent='保存済み'}catch(error){button.dataset.imageError=error.name;button.textContent='保存失敗';console.error(error)}setTimeout(()=>button.textContent='画像保存',1200)});
